-- Fail-closed exact-row checks for the BECE gap beta release 237-248.
PRAGMA foreign_keys = ON;
CREATE TEMP TABLE _bece_gap_beta_preflight_guard (valid INTEGER NOT NULL CHECK (valid = 1));
CREATE TEMP TABLE _bece_gap_preflight_expected_237 (question_id TEXT PRIMARY KEY, topic_id TEXT NOT NULL, subject_id TEXT NOT NULL, exam_type_id TEXT NOT NULL, question_text TEXT NOT NULL, question_type TEXT NOT NULL, options TEXT NOT NULL, correct_answer TEXT NOT NULL, explanation TEXT NOT NULL, difficulty TEXT NOT NULL, points INTEGER NOT NULL, marks INTEGER NOT NULL, time_limit INTEGER NOT NULL, command_word TEXT NOT NULL, assessment_objective TEXT NOT NULL);
DELETE FROM _bece_gap_preflight_expected_237;
  AND (SELECT COUNT(*) FROM question_content_releases r JOIN _bece_gap_preflight_expected_237 e ON e.question_id=r.question_id WHERE r.batch_id IS 'bece-bdt-gap-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)=10
  AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _bece_gap_preflight_expected_237 e ON e.question_id=l.entity_id WHERE l.migration_id IS '237_bece_bdt_gap_beta_part_1' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-bdt-gap-beta-001')=10
  AND (SELECT COUNT(*) FROM question_bank_remediation_log WHERE migration_id='237_bece_bdt_gap_beta_part_1')=10
  AND NOT EXISTS (SELECT 1 FROM questions q JOIN _bece_gap_preflight_expected_237 e ON e.question_id=q.id JOIN questions other ON other.id IS NOT q.id AND lower(trim(other.question_text))=lower(trim(q.question_text)))
THEN 1 ELSE 0 END;
DROP TABLE _bece_gap_preflight_expected_237;
