  (SELECT COUNT(*) FROM questions q JOIN _bece_gap_preflight_expected_238 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10
INSERT INTO _bece_gap_preflight_expected_239(question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) VALUES
  ('q_bece_bdt_gap_b001_021','topic_bece_bdt_electricals','subj_bece_bdt','exam_bece','A wall switch is off but a tester still detects voltage at the fitting. What should the learner conclude?','multiple_choice','["A. The circuit must be isolated at the supply and proved dead before any work","B. The wall switch alone guarantees safe isolation","C. Wet hands will remove the remaining voltage","D. A larger breaker will make the fitting safe"]','A','A local switch may be wired incorrectly or may not isolate every live conductor, so safe work requires supply isolation and verification with a suitable tester. Therefore the correct answer is A: The circuit must be isolated at the supply and proved dead before any work.','medium',1,1,90,'Apply','AO2'),
  ('q_bece_bdt_gap_b001_022','topic_bece_bdt_electricals','subj_bece_bdt','exam_bece','What shows an intentional conductor junction in a circuit drawing?','multiple_choice','["A. A north arrow","B. A roof triangle","C. A solid dot at the conductor intersection","D. A broken dimension line"]','C','A solid junction dot distinguishes a true electrical connection from crossing conductors that pass without joining. Therefore the correct answer is C: A solid dot at the conductor intersection.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_bdt_gap_b001_023','topic_bece_bdt_electricals','subj_bece_bdt','exam_bece','Why should electrical work never be done with wet hands?','multiple_choice','["A. Water turns off the grid","B. Wet hands thicken insulation","C. Moisture stops current","D. Moisture can lower skin resistance and increase shock current"]','D','Moisture can reduce the body’s resistance, allowing a larger and more dangerous current through a person contacting a live part. Therefore the correct answer is D: Moisture can lower skin resistance and increase shock current.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_024','topic_bece_bdt_electricals','subj_bece_bdt','exam_bece','What does a circuit breaker do after detecting serious overcurrent?','multiple_choice','["A. Generate extra current","B. Join live and neutral","C. Open the circuit automatically; it can be reset after the fault is cleared","D. Hide damaged insulation"]','C','A breaker trips to disconnect unsafe current and can normally be reset only after the underlying fault has been corrected. Therefore the correct answer is C: Open the circuit automatically; it can be reset after the fault is cleared.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_025','topic_bece_bdt_electricals','subj_bece_bdt','exam_bece','Which action reduces electrical energy waste in a classroom?','multiple_choice','["A. Leave idle chargers powered","B. Keep damaged cables","C. Block equipment ventilation","D. Switch off unused lights and equipment at the source"]','D','Turning unused loads off prevents unnecessary consumption and reduces avoidable heat, operating cost and equipment wear. Therefore the correct answer is D: Switch off unused lights and equipment at the source.','medium',1,1,90,'Apply','AO2'),
  ('q_bece_bdt_gap_b001_026','topic_bece_bdt_electricals','subj_bece_bdt','exam_bece','A person is receiving an electric shock. What is the safest first response?','multiple_choice','["A. Disconnect electricity without directly touching the person","B. Pull them with wet hands","C. Pour water on the appliance","D. Hold the bare conductor"]','A','The supply should be isolated before contact because touching the casualty while current flows can shock the rescuer too. Therefore the correct answer is A: Disconnect electricity without directly touching the person.','hard',1,1,90,'Apply','AO3'),
  ('q_bece_bdt_gap_b001_027','topic_bece_bdt_electricals','subj_bece_bdt','exam_bece','What matters most when selecting a replacement fuse?','multiple_choice','["A. The wall colour","B. The circuit’s specified current rating and fuse type","C. The owner’s age","D. The appliance name length"]','B','A replacement must match the protective design so it carries normal current but interrupts a fault before equipment exceeds safe limits. Therefore the correct answer is B: The circuit’s specified current rating and fuse type.','medium',1,1,90,'Select','AO2'),
  ('q_bece_bdt_gap_b001_028','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','Why conduct market research before producing an item for sale?','multiple_choice','["A. To learn what customers need, value and will buy","B. To guarantee sales at any price","C. To avoid competitors","D. To replace costs with guesses"]','A','Market research supplies evidence about customers, alternatives, prices and demand, helping design an offer with a realistic chance of sale. Therefore the correct answer is A: To learn what customers need, value and will buy.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_029','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','Which cost changes most when a craft business makes more units?','multiple_choice','["A. Annual registration already paid","B. Material used for the additional units","C. Fixed monthly rent","D. A permanent workbench"]','B','Material consumption rises with output and is a variable cost, while rent and long-lived equipment do not change unit by unit. Therefore the correct answer is B: Material used for the additional units.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_030','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','How is profit calculated for a small production period?','multiple_choice','["A. Add costs to borrowing","B. Subtract revenue from customers","C. Multiply price by owner age","D. Subtract total costs from sales revenue"]','D','Profit is the amount remaining after relevant costs are deducted from revenue, so incomplete cost records give a misleading result. Therefore the correct answer is D: Subtract total costs from sales revenue.','easy',1,1,90,'Calculate','AO1');
INSERT INTO _bece_gap_beta_preflight_guard(valid) SELECT CASE WHEN
  (SELECT COUNT(*) FROM questions q JOIN _bece_gap_preflight_expected_239 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10
INSERT INTO _bece_gap_preflight_expected_240(question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) VALUES
  ('q_bece_bdt_gap_b001_031','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','What does a value proposition explain?','multiple_choice','["A. Only the owner’s hobbies","B. Why defects should be ignored","C. The useful benefit that makes the product worth choosing","D. How to hide price"]','C','A value proposition connects product features to a customer need and distinguishes the offer from available alternatives. Therefore the correct answer is C: The useful benefit that makes the product worth choosing.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_032','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','Why record daily sales and expenses separately?','multiple_choice','["A. To make receipts unverifiable","B. To mix household money","C. To stop returns","D. To track cash movement and performance accurately"]','D','Separate records show what the business earned and spent, support profit checks and make unusual losses easier to investigate. Therefore the correct answer is D: To track cash movement and performance accurately.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_033','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','What is the break-even point?','multiple_choice','["A. The sales level where total revenue equals total cost","B. When nobody knows the product","C. The highest imagined price","D. When every cost is zero"]','A','At break-even the enterprise covers fixed and variable costs but has not made a profit, so later sales can contribute to profit. Therefore the correct answer is A: The sales level where total revenue equals total cost.','easy',1,1,90,'Define','AO1'),
  ('q_bece_bdt_gap_b001_034','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','Which pricing approach is most responsible?','multiple_choice','["A. Copy an unrelated high price","B. Calculate costs, customer value and realistic market prices","C. Ignore labour and materials","D. Change prices randomly"]','B','Sound pricing covers relevant costs, reflects product value and remains credible against alternatives while sustaining quality. Therefore the correct answer is B: Calculate costs, customer value and realistic market prices.','hard',1,1,90,'Evaluate','AO3'),
  ('q_bece_bdt_gap_b001_035','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','How can customer feedback improve a product?','multiple_choice','["A. Prove complaints are dishonest","B. Remove the need to test","C. Reveal defects and unmet needs for the next revision","D. Guarantee one design suits all"]','C','Structured feedback identifies recurring user problems and priorities that the maker can verify before improving the design. Therefore the correct answer is C: Reveal defects and unmet needs for the next revision.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_036','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','What is the purpose of quality control?','multiple_choice','["A. Hide defective units","B. Check that outputs consistently meet agreed requirements","C. Increase unmeasured waste","D. Avoid dimensions"]','B','Quality control compares work with defined standards at useful stages, allowing faults to be corrected before products reach customers. Therefore the correct answer is B: Check that outputs consistently meet agreed requirements.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_037','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','Why keep business and household money separate?','multiple_choice','["A. To prevent budgets","B. To hide withdrawals","C. To know the enterprise’s true cash position","D. To remove receipts"]','C','Separating funds makes income, costs and drawings traceable and helps the owner decide what the enterprise can safely spend. Therefore the correct answer is C: To know the enterprise’s true cash position.','medium',1,1,90,'Interpret','AO2'),
  ('q_bece_bdt_gap_b001_038','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','What does positive cash flow mean for a period?','multiple_choice','["A. More cash entered the business than left it","B. There were no sales","C. All sales were unpaid","D. Payment dates were ignored"]','A','Positive cash flow means receipts exceeded payments for that period, although profitability and future obligations still need review. Therefore the correct answer is A: More cash entered the business than left it.','easy',1,1,90,'Interpret','AO1'),
  ('q_bece_bdt_gap_b001_039','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','Which advertising statement is ethical?','multiple_choice','["A. A false no-failure claim","B. A hidden charge","C. A fabricated endorsement","D. A truthful description of tested features and actual price"]','D','Ethical promotion gives customers accurate material information and avoids deceptive claims, supporting informed choice and trust. Therefore the correct answer is D: A truthful description of tested features and actual price.','hard',1,1,90,'Explain','AO3'),
  ('q_bece_bdt_gap_b001_040','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','Why prepare a business plan before seeking a small loan?','multiple_choice','["A. To guarantee approval","B. To replace records","C. To explain market, operations, costs, risks and repayment capacity","D. To prove conditions never change"]','C','A business plan organizes enterprise assumptions and helps owner and lender judge whether expected cash flows support repayment. Therefore the correct answer is C: To explain market, operations, costs, risks and repayment capacity.','hard',1,1,90,'Explain','AO3');
INSERT INTO _bece_gap_beta_preflight_guard(valid) SELECT CASE WHEN
  (SELECT COUNT(*) FROM questions q JOIN _bece_gap_preflight_expected_240 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10
INSERT INTO _bece_gap_preflight_expected_241(question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) VALUES
  ('q_bece_math_sets_b001_001','topic_bece_math_sets','subj_bece_math','exam_bece','Which notation states that 5 is an element of set A?','multiple_choice','["A. 5 ∈ A","B. 5 ⊂ A","C. 5 ∉ A","D. A ∈ 5"]','A','The symbol ∈ means “is an element of,” so 5 ∈ A states that the object 5 belongs to the collection called set A. Therefore the correct answer is A: 5 ∈ A.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_math_sets_b001_002','topic_bece_math_sets','subj_bece_math','exam_bece','If B = {2, 4, 6, 8}, what is n(B)?','multiple_choice','["A. 2","B. 8","C. 20","D. 4"]','D','Cardinality n(B) counts distinct elements. The listed elements are 2, 4, 6 and 8, so the set contains four elements. Therefore the correct answer is D: 4.','easy',1,1,90,'Calculate','AO1'),
  ('q_bece_math_sets_b001_003','topic_bece_math_sets','subj_bece_math','exam_bece','Which roster lists odd whole numbers below 10?','multiple_choice','["A. {2, 4, 6, 8}","B. {1, 3, 5, 7, 9}","C. {1, 2, 3, 4, 5}","D. {3, 6, 9}"]','B','Odd whole numbers are not divisible by 2. Below 10 they are exactly 1, 3, 5, 7 and 9. Therefore the correct answer is B: {1, 3, 5, 7, 9}.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_math_sets_b001_004','topic_bece_math_sets','subj_bece_math','exam_bece','What is the empty set?','multiple_choice','["A. A set containing zero","B. A set containing no elements","C. A set containing everything","D. A set with duplicate entries"]','B','The empty set has cardinality zero and is written ∅ or { }. The set {0} differs because it contains one element. Therefore the correct answer is B: A set containing no elements.','easy',1,1,90,'Define','AO1'),
  ('q_bece_math_sets_b001_005','topic_bece_math_sets','subj_bece_math','exam_bece','Given A = {1, 2} and B = {1, 2, 3}, which is true?','multiple_choice','["A. B is a subset of A","B. A and B are disjoint","C. A has more elements","D. A is a proper subset of B"]','D','Every element of A occurs in B and B has the additional element 3, so A is a proper subset of B. Therefore the correct answer is D: A is a proper subset of B.','medium',1,1,90,'Determine','AO2'),
  ('q_bece_math_sets_b001_006','topic_bece_math_sets','subj_bece_math','exam_bece','What is the intersection of P = {a, b, c} and Q = {b, c, d}?','multiple_choice','["A. {b, c}","B. {a, d}","C. {a, b, c, d}","D. {b, c, d}"]','A','Intersection contains elements common to both sets. Only b and c appear in both P and Q. Therefore the correct answer is A: {b, c}.','easy',1,1,90,'Determine','AO1'),
  ('q_bece_math_sets_b001_007','topic_bece_math_sets','subj_bece_math','exam_bece','What is the union of P = {a, b, c} and Q = {b, c, d}?','multiple_choice','["A. {b, c}","B. {a, d}","C. {a, b, c, d}","D. {a, b, c, b, c, d}"]','C','Union includes every distinct element appearing in either set, with repeated elements written only once. Therefore the correct answer is C: {a, b, c, d}.','easy',1,1,90,'Determine','AO1'),
  ('q_bece_math_sets_b001_008','topic_bece_math_sets','subj_bece_math','exam_bece','Two sets have no common element. How are they described?','multiple_choice','["A. Equivalent fractions","B. Universal sets","C. Improper subsets","D. Disjoint sets"]','D','Disjoint sets have an empty intersection, written A ∩ B = ∅, because no object belongs to both sets. Therefore the correct answer is D: Disjoint sets.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_math_sets_b001_009','topic_bece_math_sets','subj_bece_math','exam_bece','Let U = {1, 2, 3, 4, 5} and A = {2, 4}. What is A′?','multiple_choice','["A. {2, 4}","B. {1, 2, 3, 4, 5}","C. {1, 3, 5}","D. {3, 5}"]','C','The complement contains elements of U not in A. Removing 2 and 4 leaves 1, 3 and 5. Therefore the correct answer is C: {1, 3, 5}.','medium',1,1,90,'Determine','AO2'),
  ('q_bece_math_sets_b001_010','topic_bece_math_sets','subj_bece_math','exam_bece','What role does a universal set play?','multiple_choice','["A. It contains one element","B. It defines all elements considered in that context","C. It equals the empty set","D. It excludes named sets"]','B','The universal set gives the complete domain, so complements and regions outside named subsets are interpreted relative to it. Therefore the correct answer is B: It defines all elements considered in that context.','medium',1,1,90,'Explain','AO2');
