  (SELECT COUNT(*) FROM questions q JOIN _bece_gap_preflight_expected_242 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10
INSERT INTO _bece_gap_preflight_expected_243(question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) VALUES
  ('q_bece_math_sets_b001_021','topic_bece_math_sets','subj_bece_math','exam_bece','If A={1,2,3,4} and B={3,4,5}, what is A \ B?','multiple_choice','["A. {3, 4}","B. {5}","C. {1, 2, 5}","D. {1, 2}"]','D','Remove the common elements 3 and 4 from A. The remaining A-only elements are 1 and 2. Therefore the correct answer is D: {1, 2}.','medium',1,1,90,'Determine','AO2'),
  ('q_bece_math_sets_b001_022','topic_bece_math_sets','subj_bece_math','exam_bece','Among 30 learners, 18 like rice, 16 like yam and 8 like both. How many like neither?','multiple_choice','["A. 4","B. 26","C. 10","D. 12"]','A','The union is 18+16−8=26. Therefore 30−26=4 learners are outside both sets. Therefore the correct answer is A: 4.','hard',1,1,90,'Calculate','AO3'),
  ('q_bece_math_sets_b001_023','topic_bece_math_sets','subj_bece_math','exam_bece','Twenty study French, fourteen study ICT and six study both. How many study only French?','multiple_choice','["A. 20","B. 14","C. 8","D. 26"]','B','The French total includes the six in the overlap, so the French-only region is 20−6=14. Therefore the correct answer is B: 14.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_024','topic_bece_math_sets','subj_bece_math','exam_bece','If n(U)=50 and n(A)=32, find n(A′).','multiple_choice','["A. 18","B. 82","C. 32","D. 2"]','A','A and its complement partition U, so n(A′)=n(U)−n(A)=50−32=18. Therefore the correct answer is A: 18.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_025','topic_bece_math_sets','subj_bece_math','exam_bece','Which set lists prime numbers below 10?','multiple_choice','["A. {1, 2, 3, 5, 7}","B. {2, 3, 5, 7}","C. {2, 4, 6, 8}","D. {3, 6, 9}"]','B','Primes greater than 1 have exactly two positive factors. Below 10 these are 2, 3, 5 and 7. Therefore the correct answer is B: {2, 3, 5, 7}.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_math_sets_b001_026','topic_bece_math_sets','subj_bece_math','exam_bece','If disjoint A and B have 9 and 11 elements, find n(A∪B).','multiple_choice','["A. 2","B. 99","C. 11","D. 20"]','D','Disjoint sets have zero overlap, so the union count is 9+11−0=20. Therefore the correct answer is D: 20.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_027','topic_bece_math_sets','subj_bece_math','exam_bece','What does the region outside A but inside U represent?','multiple_choice','["A. A ∩ A","B. An empty universal set","C. A′","D. Only A’s boundary"]','C','Every point inside U but outside circle A belongs to the complement of A, denoted A′ or Aᶜ. Therefore the correct answer is C: A′.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_math_sets_b001_028','topic_bece_math_sets','subj_bece_math','exam_bece','If A is multiples of 4 and B is even numbers, which is correct?','multiple_choice','["A. B ⊆ A","B. A ∩ B = ∅","C. A = ∅","D. A ⊆ B"]','D','Every multiple of 4 is divisible by 2 and therefore even, although not every even number is a multiple of 4. Therefore the correct answer is D: A ⊆ B.','hard',1,1,90,'Deduce','AO3'),
  ('q_bece_math_sets_b001_029','topic_bece_math_sets','subj_bece_math','exam_bece','A set contains the letters in LEVEL. How many distinct elements are there?','multiple_choice','["A. 3","B. 5","C. 4","D. 2"]','A','Repeated letters count once in a set. LEVEL contains the distinct letters L, E and V, giving cardinality 3. Therefore the correct answer is A: 3.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_030','topic_bece_math_sets','subj_bece_math','exam_bece','Which pair is disjoint?','multiple_choice','["A. {1,2} and {2,3}","B. {1,3,5} and {2,4,6}","C. {a,b} and {b,c}","D. {4,8} and {2,4}"]','B','Odd numbers in the first set share no member with the even numbers in the second; every other pair overlaps. Therefore the correct answer is B: {1,3,5} and {2,4,6}.','medium',1,1,90,'Compare','AO2');
INSERT INTO _bece_gap_beta_preflight_guard(valid) SELECT CASE WHEN
  (SELECT COUNT(*) FROM questions q JOIN _bece_gap_preflight_expected_243 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10
INSERT INTO _bece_gap_preflight_expected_244(question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) VALUES
  ('q_bece_math_sets_b001_031','topic_bece_math_sets','subj_bece_math','exam_bece','If A ∩ B = A, what follows?','multiple_choice','["A. A and B are disjoint","B. B is empty","C. A ⊆ B","D. A has no B elements"]','C','If intersection leaves all of A unchanged, every member of A must already belong to B. Therefore the correct answer is C: A ⊆ B.','hard',1,1,90,'Deduce','AO3'),
  ('q_bece_math_sets_b001_032','topic_bece_math_sets','subj_bece_math','exam_bece','If A ∪ B = B, what follows?','multiple_choice','["A. B ⊆ A only","B. A ⊆ B","C. A and B are disjoint","D. B is empty"]','B','Adding A to B produces nothing new only when every member of A is already in B. Therefore the correct answer is B: A ⊆ B.','hard',1,1,90,'Deduce','AO3'),
  ('q_bece_math_sets_b001_033','topic_bece_math_sets','subj_bece_math','exam_bece','Eleven choose art only and five choose both art and music. How many choose art?','multiple_choice','["A. 11","B. 23","C. 16","D. 18"]','C','The art set contains the art-only region plus the overlap, so 11+5=16 learners choose art. Therefore the correct answer is C: 16.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_034','topic_bece_math_sets','subj_bece_math','exam_bece','A Venn diagram has 6 in A only, 3 in both and 8 in B only. Find n(A∪B).','multiple_choice','["A. 17","B. 9","C. 11","D. 14"]','A','The union contains all three separate regions inside the circles, so 6+3+8=17. Therefore the correct answer is A: 17.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_035','topic_bece_math_sets','subj_bece_math','exam_bece','If U={1,2,3,4,5,6} and A={2,4,6}, which option belongs to A′?','multiple_choice','["A. 2","B. 4","C. 6","D. 5"]','D','The complement is {1,3,5}. Among the choices, only 5 lies outside A while remaining inside U. Therefore the correct answer is D: 5.','medium',1,1,90,'Determine','AO2'),
  ('q_bece_math_sets_b001_036','topic_bece_math_sets','subj_bece_math','exam_bece','What happens when an entry is repeated in roster notation?','multiple_choice','["A. Cardinality always rises","B. The set becomes empty","C. It does not create a new set element","D. Letters become invalid"]','C','Membership matters, not repetition. Thus {1,1,2} represents the same set as {1,2}. Therefore the correct answer is C: It does not create a new set element.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_math_sets_b001_037','topic_bece_math_sets','subj_bece_math','exam_bece','If n(A)=12, n(A∪B)=20 and n(A∩B)=5, find n(B).','multiple_choice','["A. 13","B. 3","C. 17","D. 37"]','A','Substitute into 20=12+n(B)−5. Rearranging gives n(B)=13. Therefore the correct answer is A: 13.','hard',1,1,90,'Calculate','AO3'),
  ('q_bece_math_sets_b001_038','topic_bece_math_sets','subj_bece_math','exam_bece','Of 35 people, 15 use bus only, 9 walk only and 6 do both. How many use neither?','multiple_choice','["A. 30","B. 11","C. 20","D. 5"]','D','The three inside regions total 15+9+6=30, leaving 35−30=5 outside both. Therefore the correct answer is D: 5.','hard',1,1,90,'Calculate','AO3'),
  ('q_bece_math_sets_b001_039','topic_bece_math_sets','subj_bece_math','exam_bece','What is the intersection of any set A with the empty set?','multiple_choice','["A. A","B. ∅","C. {0}","D. U"]','B','The empty set has no elements, so no element can be common to A and ∅; their intersection is empty. Therefore the correct answer is B: ∅.','easy',1,1,90,'Determine','AO1'),
  ('q_bece_math_sets_b001_040','topic_bece_math_sets','subj_bece_math','exam_bece','What is the union of any set A with the empty set?','multiple_choice','["A. ∅","B. A′","C. A","D. {A,∅}"]','C','Union collects members from either set. Since ∅ contributes none, the result contains exactly the members of A. Therefore the correct answer is C: A.','easy',1,1,90,'Determine','AO1');
INSERT INTO _bece_gap_beta_preflight_guard(valid) SELECT CASE WHEN
  (SELECT COUNT(*) FROM questions q JOIN _bece_gap_preflight_expected_244 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10
INSERT INTO _bece_gap_preflight_expected_245(question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) VALUES
  ('q_bece_science_agric_b001_001','topic_bece_science_agric','subj_bece_science','exam_bece','Which soil type usually holds the most water?','multiple_choice','["A. Sandy soil","B. Gravel","C. Coarse stones","D. Clay soil"]','D','Clay has very small particles and pore spaces, so water drains more slowly and is retained more strongly than in sandy soil. Therefore the correct answer is D: Clay soil.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_science_agric_b001_002','topic_bece_science_agric','subj_bece_science','exam_bece','Why is loam often suitable for crop growth?','multiple_choice','["A. It balances drainage, water retention, air and nutrients","B. It contains no mineral particles","C. It prevents every pest","D. It never needs organic matter"]','A','Loam combines sand, silt, clay and organic matter in proportions that support roots, drainage, aeration and nutrient supply. Therefore the correct answer is A: It balances drainage, water retention, air and nutrients.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_science_agric_b001_003','topic_bece_science_agric','subj_bece_science','exam_bece','What does soil pH measure?','multiple_choice','["A. The number of earthworms","B. The soil’s total mass","C. How acidic or alkaline the soil is","D. The height of crops"]','C','Soil pH expresses acidity or alkalinity and affects nutrient availability and the activity of many soil organisms. Therefore the correct answer is C: How acidic or alkaline the soil is.','easy',1,1,90,'Define','AO1'),
  ('q_bece_science_agric_b001_004','topic_bece_science_agric','subj_bece_science','exam_bece','How does humus improve soil?','multiple_choice','["A. It seals all pore spaces","B. It removes all organisms","C. It turns soil into rock","D. It adds nutrients and improves structure and water holding"]','D','Humus from decomposed material contributes nutrients, binds particles into stable aggregates and helps soil retain useful moisture. Therefore the correct answer is D: It adds nutrients and improves structure and water holding.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_science_agric_b001_005','topic_bece_science_agric','subj_bece_science','exam_bece','Which practice reduces erosion on a sloping farm?','multiple_choice','["A. Making channels straight downhill","B. Leaving soil bare","C. Planting along contour lines","D. Burning all residues"]','C','Contour farming slows runoff across the slope, allowing more infiltration and reducing the water’s ability to carry soil away. Therefore the correct answer is C: Planting along contour lines.','medium',1,1,90,'Apply','AO2'),
  ('q_bece_science_agric_b001_006','topic_bece_science_agric','subj_bece_science','exam_bece','Why is mulch placed around crops?','multiple_choice','["A. To stop roots receiving air","B. To reduce evaporation, suppress weeds and protect soil","C. To increase runoff speed","D. To attract every crop pest"]','B','Mulch covers the surface, conserving moisture, reducing weed emergence and cushioning soil against raindrop impact. Therefore the correct answer is B: To reduce evaporation, suppress weeds and protect soil.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_science_agric_b001_007','topic_bece_science_agric','subj_bece_science','exam_bece','Two plots grew maize last season. One is planted with cowpea before maize returns; the other repeats maize. What benefit is expected in the first plot?','multiple_choice','["A. The cowpea phase can improve nitrogen supply and interrupt maize-specific pests","B. Cowpea removes every soil nutrient before maize","C. Repeating maize always eliminates crop diseases","D. The rotation makes rainfall unnecessary"]','A','Cowpea is a legume associated with nitrogen-fixing bacteria, and changing the host crop can interrupt pests and diseases that build up under continuous maize. Therefore the correct answer is A: The cowpea phase can improve nitrogen supply and interrupt maize-specific pests.','hard',1,1,90,'Explain','AO3'),
  ('q_bece_science_agric_b001_008','topic_bece_science_agric','subj_bece_science','exam_bece','Which seed is best for planting?','multiple_choice','["A. A healthy mature seed of a suitable variety","B. A mouldy damaged seed","C. An immature shrivelled seed","D. A seed from an unknown diseased plant"]','A','Healthy mature seed with known varietal qualities has a better chance of germinating uniformly and establishing vigorous plants. Therefore the correct answer is A: A healthy mature seed of a suitable variety.','medium',1,1,90,'Select','AO2'),
  ('q_bece_science_agric_b001_009','topic_bece_science_agric','subj_bece_science','exam_bece','What three conditions are generally needed for seed germination?','multiple_choice','["A. Salt, smoke and darkness only","B. Fertiliser, pesticide and wind","C. Water, oxygen and suitable temperature","D. Clay, stones and bright paint"]','C','Water activates metabolism, oxygen supports respiration and a suitable temperature allows enzymes to function during germination. Therefore the correct answer is C: Water, oxygen and suitable temperature.','medium',1,1,90,'Identify','AO2'),
  ('q_bece_science_agric_b001_010','topic_bece_science_agric','subj_bece_science','exam_bece','Why is correct crop spacing important?','multiple_choice','["A. It guarantees every seed survives","B. It removes all labour","C. It makes soil nutrients unlimited","D. It limits competition while allowing useful field coverage"]','D','Appropriate spacing balances access to light, water and nutrients with plant population, air movement and management access. Therefore the correct answer is D: It limits competition while allowing useful field coverage.','medium',1,1,90,'Explain','AO2');
